    "linhkienhaomon":  {
                           "id":  "linhkienhaomon",
                           "name":  "Linh Kiện Hao Mòn",
                           "original_name":  "磨损部件",
                           "rarity":  1,
                           "category":  "Sản Vật Kỳ Ba",
                           "category_zh":  "材料",
                           "intro":  "Bộ phận cơ khí rơi ra từ Kỳ Ba tộc Cơ Ngẫu, có nhiều công dụng.",
                           "intro_zh":  "机偶族奇波掉落的部件，具有多种用途。",
                           "description":  "Linh kiện cơ khí hơi hao mòn, là then chốt duy trì sự vận hành cơ thể của Kỳ Ba tộc Cơ Ngẫu. Cùng với sự hao mòn dần của những bộ phận này, Kỳ Ba Cơ Ngẫu cũng từng bước hoàn thành vòng đời của chúng.",
                           "description_zh":  "略有磨损的机械部件，是维系机偶族奇波身体运转的关键。随着这些部件逐渐磨损，机偶族奇波也逐步完成着它们的生命周期。",
                           "acquisition_sources":  [
                                                       "Sản vật Mục Trường Gia Viên"
                                                   ],
                           "acquisition_sources_zh":  "家园牧场产出",
                           "image":  "../../assets/materials/linhkienhaomon.png"
                       },
    "longtominmang":  {
                          "id":  "longtominmang",
                          "name":  "Lông Tơ Mịn Màng",
                          "original_name":  "细密软绒",
                          "rarity":  1,
                          "category":  "Sản Vật Kỳ Ba",
                          "category_zh":  "材料",
                          "intro":  "Lông tơ mềm mại rơi ra từ Kỳ Ba tộc Thú Hình, có nhiều công dụng.",
                          "intro_zh":  "兽形族奇波掉落的绒毛，具有多种用途。",
                          "description":  "Lớp lông tơ mọc sát da của Kỳ Ba tộc Thú Hình, có đặc tính giữ ấm và chống thấm nước cực tốt. Chúng có chu kỳ thay lông khá dài, rất dễ thu thập nên trở thành một loại nguyên liệu Kỳ Ba vô cùng thông dụng.",
                          "description_zh":  "兽形族奇波贴近皮肤生长的细绒，具有极佳的保暖性与疏水性。这种细密的软绒按说应该难以直接获得，但它们有着很长的换绒周期，收集起来十分容易，也因此成为了一种常见的奇波材料。\u003cbr\u003e有智慧种族戏称，这些奇波换绒的规律为一约换两次，一次换半约。",
                          "acquisition_sources":  [
                                                      "Sản vật Mục Trường Gia Viên"
                                                  ],
                          "acquisition_sources_zh":  "家园牧场产出",
                          "image":  "../../assets/materials/longtominmang.png"
                      },
    "voxacroirung":  {
                         "id":  "voxacroirung",
                         "name":  "Vỏ Xác Rơi Rụng",
                         "original_name":  "遗落旧蜕",
                         "rarity":  3,
                         "category":  "Sản Vật Kỳ Ba",
                         "category_zh":  "材料",
                         "intro":  "Xác lột của Kỳ Ba tộc Thoái Hình thỉnh thoảng đánh rơi.",
                         "intro_zh":  "蜕形族奇波偶尔会掉落的蜕壳。",
                         "description":  "Lớp xác lột rơi rụng khi Kỳ Ba tộc Thoái Hình bước sang một giai đoạn phát triển mới, tượng trưng cho sự tái sinh. Quá trình lột xác thường rất nguy hiểm, và lớp vỏ lột tương đối nguyên vẹn này là minh chứng rằng chúng đã vượt qua giới hạn của chính mình.",
                         "description_zh":  "蜕形族奇波成长到崭新的阶段后遗落的蜕壳，象征了蜕形族奇波的新生。\u003cbr\u003e蜕壳时的奇波处于相当危险的境地之中：它们专注于蜕壳，无暇应对外界的危险，而这枚形态较为完整的旧蜕便是蜕形族已经超越自我的证明。",
                         "acquisition_sources":  [
                                                     "Sản vật Mục Trường Gia Viên"
                                                 ],
                         "acquisition_sources_zh":  "家园牧场产出",
                         "image":  "../../assets/materials/voxacroirung.png"
                     },
    "loihangdinh":  {
                        "id":  "loihangdinh",
                        "name":  "Lõi Hằng Định",
                        "original_name":  "恒定核心",
                        "rarity":  3,
                        "category":  "Sản Vật Kỳ Ba",
                        "category_zh":  "材料",
                        "intro":  "Lõi cơ khí của Kỳ Ba tộc Cơ Ngẫu thỉnh thoảng đánh rơi.",
                        "intro_zh":  "机偶族奇波偶尔掉落的核心。",
                        "description":  "Khác với các linh kiện dễ bị hao mòn theo thời gian, trái tim cơ khí hình thể máy móc này luôn giữ được vẻ sáng bóng và ngăn nắp. Bánh răng và dây xích chuyển động không biết mệt mỏi, phản chiếu sự ổn định vĩnh hằng của tộc Cơ Ngẫu.",
                        "description_zh":  "与会逐渐磨损的部件不同，这枚机械形态的机偶之心永远保持光洁整齐。齿轮与链条不知疲倦地转动，正如机偶族恒常不变的稳定内核。",
                        "acquisition_sources":  [
                                                    "Sản vật Mục Trường Gia Viên"
                                                ],
                        "acquisition_sources_zh":  "家园牧场产出",
                        "image":  "../../assets/materials/loihangdinh.png"
                    },
    "sunglinhthu":  {
                        "id":  "sunglinhthu",
                        "name":  "Sừng Linh Thú",
                        "original_name":  "兽灵之角",
                        "rarity":  3,
                        "category":  "Sản Vật Kỳ Ba",
                        "category_zh":  "材料",
                        "intro":  "Chiếc sừng của Kỳ Ba tộc Thú Hình thỉnh thoảng đánh rơi.",
                        "intro_zh":  "兽形族奇波偶尔会掉落的角。",
                        "description":  "Cặp sừng ngưng tụ từ lòng dũng cảm của Kỳ Ba tộc Thú Hình, đại diện cho ý chí kiên định không bao giờ chùn bước. Tương truyền, mũi nhọn của chiếc sừng này sẽ luôn hướng về phía kẻ địch.",
                        "description_zh":  "由兽形族奇波的勇猛凝成的兽角，代表了兽形族奇波勇往无前的勇气。\u003cbr\u003e据说，这枚兽角的尖端永远都会指向敌人的方向。",
                        "acquisition_sources":  [
                                                    "Sản vật Mục Trường Gia Viên"
                                                ],
                        "acquisition_sources_zh":  "家园牧场产出",
                        "image":  "../../assets/materials/sunglinhthu.png"
                    },
